        dlg("c01_67", "act3", "dying_sailor", "古斯塔夫·约翰森", "[shouting] [desperately] 八个人只逃回两个！那座绿色的山滑进海里追上来了！蒸汽压不够甩掉它——与其等死，老子驾船撞碎它！舵轮打死，全速迎头冲过去！", stability=0.0, acoustic_space="memory_echo", gap_after_s=0.22),
        sfx("c01_68", "act3", "Colossal steel ship bow smashing violently into a massive wet gelatinous mass bursting with explosive sulfurous spray and crashing ocean waves, pure foley, no human voice", duration_seconds=3.4, placement="overlay_next", gap_after_s=0.18, director_note="钢铁船首劈开克苏鲁绿雾"),
        dlg("c01_69", "act3", "narrator_deep", "档案片旁白", "[dramatically] 警戒号锋利的铁船首狠狠劈进那团山岳般的粘稠绿肉！一声惊天动地的闷爆，腐烂腥臭的绿雾炸满整片天空，几乎熏昏甲板上的人！可约翰森死死抓着舵轮回头望了一眼，灵魂瞬间碎成两半——", stability=0.0, gap_after_s=0.24),
        dlg("c01_70", "act3", "dying_sailor", "古斯塔夫·约翰森", "[hoarsely] [crying] 被船头劈成两半的绿雾，根本没有消散！它在海面上自己翻滚、聚拢、重新长成了那尊顶天立地的怪物！只是岛上那场四月二号的特大风暴，又把整座石城重新压回了海底……", stability=0.0, acoustic_space="memory_echo", gap_after_s=0.34),
