        sfx("c01_77", "act4", "Three slow heavy wet knocks echoing on a solid oak front door in midnight rain followed by tense resonant silence, pure foley, no human voice", duration_seconds=2.8, gap_after_s=0.26, director_note="深夜橡木前门响起三声敲门"),
        dlg("c01_78", "act4", "archivist_narrator", "弗朗西斯·瑟斯顿", "[whispers] 他们上台阶了……门响了。不管谁将来打开这只铁盒——千万别去查那组经纬度。", stability=0.0, acoustic_space="studio_warm", gap_after_s=0.34),
