        dlg("c02_07", "act1", "young_investigator", "罗伯特·奥姆斯特德", "那年七月我刚满二十岁，趁暑假沿着新英格兰海岸访古旅行。在纽伯里波特火车站买去阿卡姆的车票时，嫌铁路票太贵，随口问了句有没有便宜一点的沿海班车。", gap_after_s=0.24),
