        dlg("c02_15", "act1", "young_investigator", "罗伯特·奥姆斯特德", "馆长悄悄告诉我，那头冠是一位疯了的印斯茅斯渔民半夜典当的，金属化验里掺着地球上罕见的诡异合金。正是这股挥之不去的诡异引力，推着我买了次日清晨那张致命车票。", gap_after_s=0.28),
        sfx("c02_16", "act1", "Rattling dilapidated 1920s motor bus engine sputtering unevenly over cracked coastal asphalt with gusty salt sea wind flapping worn canvas curtains, pure foley, no human voice", duration_seconds=3.0, gap_after_s=0.20, director_note="坐上乔·萨金特的鱼腥班车"),
        dlg("c02_17", "act1", "young_investigator", "罗伯特·奥姆斯特德", "清晨八点，我硬着头皮上了乔·萨金特的破旧班车。车厢空无一人，刺鼻的死鱼腐臭呛得我直反胃。透过后视镜，我瞥见司机灰白起皮的脖子两侧，竟排着几道像未张开鱼鳃一样的深褶！", gap_after_s=0.26),
        dlg("c02_18", "act1", "young_investigator", "罗伯特·奥姆斯特德", "他的下巴缩进去一大截，嘴唇厚得发灰，双手搭在方向盘上指节又短又宽，手背隐隐泛着青灰鳞斑。整整一路，他那双浑浊凸出的水泡眼一次都没眨过。", gap_after_s=0.26),
        dlg("c02_19", "act1", "sinister_stranger", "司机乔·萨金特", "[coldly] [eerie] 下车吧外乡人，印斯茅斯镇广场到了。你要去阿卡姆？晚上八点倒有趟回程车——前提是这破发动机别闹脾气。", stability=0.0, gap_after_s=0.24),
        dlg("c02_20", "act1", "narrator_deep", "档案片旁白", "整座海港像一具泡烂的死尸。半数乔治亚老宅用黑木板钉死，屋顶塌陷，空气里飘着潮腥霉味。昔日教堂的十字架被拆了，换成了阴森的“达贡秘教”石牌。暗窗后面，一双双死鱼眼冷冷盯着这个闯入者。", gap_after_s=0.26),
        sfx("c02_21", "act1", "Tiny brass shop door bell jingling nervously followed by hushed footsteps and a folded paper map sliding stealthily across a wooden grocery counter, pure foley, no human voice", duration_seconds=2.6, gap_after_s=0.20, director_note="杂货店外地小伙悄悄塞地图"),
        dlg("c02_22", "act1", "panicked_witness", "外地杂货店小伙", "[whispers] [rushed] 嘘！别东张西望，假装挑罐头！我是总公司从阿卡姆派来顶班的，这镇子快把我逼疯了！千万别在印斯茅斯过夜，更别让本地人知道你打听过魔鬼礁！", stability=0.0, gap_after_s=0.24),
        dlg("c02_23", "act1", "young_investigator", "罗伯特·奥姆斯特德", "[whispers] [curious] 兄弟，这儿到底藏着什么秘密？马什炼金厂大烟囱天天冒黑烟，可港口连一艘正经商船都没有，他们炼的黄金从哪儿来？", stability=0.0, gap_after_s=0.22),
        dlg("c02_24", "act1", "panicked_witness", "外地杂货店小伙", "[whispers] [terrified] 没人敢问！每逢四月底和十月底的半夜，镇上达贡秘教大厅就响起像蛙叫一样的怪咏，连警察都不敢靠近海边！还有，马什家族那些老东西早就躲进封死的顶楼不见外人了。", stability=0.0, gap_after_s=0.24),
        dlg("c02_25", "act1", "panicked_witness", "外地杂货店小伙", "[whispers] [rushed] 拿着我画的这张街道草图，上面标着联邦街、吉尔曼旅馆，还有镇北头那条长满荒草的废弃铁轨！真想听老底，就买瓶私酿威士忌找海堤边九十六岁的扎多克·艾伦——但天黑前你必须坐车走！", stability=0.0, gap_after_s=0.34),
        # --- ACT 2: Seawall Whiskey + Zadok Allen's Complete 1846 Pact Confession ---
        sfx("c02_26", "act2", "Cold Atlantic waves slapping sluggishly against crumbling stone seawall with a cork popping from a glass whiskey bottle and liquid glugging, pure foley, no human voice", duration_seconds=3.0, gap_after_s=0.20, director_note="海堤边递酒给老疯子扎多克"),
        dlg("c02_27", "act2", "mad_elder", "扎多克·艾伦", "[hoarsely] [laughs] 嘿嘿嘿……好小子，居然带了真货来！这鬼地方哪儿有正经酒喝，全镇人脑子里就剩海腥味和发疯！咕嘟——痛快！", stability=0.0, gap_after_s=0.24),
        dlg("c02_28", "act2", "young_investigator", "罗伯特·奥姆斯特德", "[calmly] 艾伦老伯，您慢慢喝，这整瓶都归您。我刚才往外海看，离岸一英里那排漆黑长条礁石，就是镇上人避之不及的魔鬼礁吗？", gap_after_s=0.24),
        dlg("c02_29", "act2", "mad_elder", "扎多克·艾伦", "[whispers] [eerie] 魔鬼礁……小子，那可不是普通礁石！水底下直插万丈深渊，下面藏着一座连上帝都管不着的海底石城！一八四六年我才十几岁，亲眼看着全镇掉进地狱里！", stability=0.0, gap_after_s=0.26),
        dlg("c02_30", "act2", "young_investigator", "罗伯特·奥姆斯特德", "[curious] 一八四六年到底发生了什么？外头都说那年印斯茅斯爆发过大瘟疫，死了一大半人，真是瘟疫吗？", gap_after_s=0.22),
        dlg("c02_31", "act2", "mad_elder", "扎多克·艾伦", "[hoarsely] [angry] 放屁的瘟疫！那是屠杀！老船长奥贝德·马什早年跑南太平洋贸易，在一座满是古怪石雕的波纳佩孤岛上，撞见一群浑身戴满奇异白金首饰的土著！", stability=0.0, gap_after_s=0.26),
        dlg("c02_32", "act2", "mad_elder", "扎多克·艾伦", "[hoarsely] [whispers] 那帮岛民从不缺鱼吃，也不怕老死！奥贝德套出他们的秘密——只要对着深海摇铃、把刻着古怪咒文的铅环沉进海底，海沟里就会游上来一群半人半蛙的深潜者！", stability=0.0, gap_after_s=0.24),
        sfx("c02_33", "act2", "Heavy lead ring splashing sharply into pitch-black deep ocean water followed by bubbling abyssal ripples echoing beneath hollow sea cliffs, pure foley, no human voice", duration_seconds=2.8, gap_after_s=0.20, director_note="铅环沉海召唤深潜者"),
        dlg("c02_34", "act2", "mad_elder", "扎多克·艾伦", "[hoarsely] 后来那群岛民被邻岛屠光了，可奥贝德已经学全了咒语！一八三八年印斯茅斯闹鱼荒，船厂倒闭、家家揭不开锅，奥贝德连夜划船去魔鬼礁，亲手把铅环扔进了黑水里！", stability=0.0, gap_after_s=0.26),
        dlg("c02_35", "act2", "mad_elder", "扎多克·艾伦", "[maniacal] [hoarsely] 从那天起，海港里的鱼多到网都拉不动，奥贝德的炼金厂日夜熔化海里送来的诡异黄金！可天下哪有白捡的便宜？怪物先要活人祭品，后来干脆逼镇上的男女跟它们立下达贡三誓、世代通婚！", stability=0.0, gap_after_s=0.26),
        dlg("c02_36", "act2", "young_investigator", "罗伯特·奥姆斯特德", "[gasps] [terrified] 达贡三誓？！难道镇上就没人反抗、没人派船去波士顿叫警察吗？", stability=0.0, gap_after_s=0.20),
        dlg("c02_37", "act2", "mad_elder", "扎多克·艾伦", "[hoarsely] [trembling] 反抗了！一八四六年那夜，我爹和镇上牧师正要报警，一百多只滑腻怪物趁大退潮从魔鬼礁爬上码头，挨家挨户踹开门抹了脖子！对外就编了个大瘟疫，把全镇教堂全改成达贡秘教！", stability=0.0, gap_after_s=0.26),
        dlg("c02_38", "act2", "mad_elder", "扎多克·艾伦", "[whispers] [eerie] 更绝望的还在后头……那些混血生下来的孩子，二十岁前看着跟常人没两样。可一过中年，眼珠往外鼓，指缝长出蹼，脖子裂开鱼鳃！到最后，他们全脱光衣服跳进黑海，在魔鬼礁底下永生不死！", stability=0.0, gap_after_s=0.26),
        dlg("c02_39", "act2", "mad_elder", "扎多克·艾伦", "[hoarsely] 如今奥贝德死了，可他的海族妻子和变了形的儿孙全活在海底石城里！他们迟早会爬上岸占领整个世界——", stability=0.0, gap_after_s=0.18),
        sfx("c02_40", "act2", "Sudden loud wet splash breaking the dark surface of distant ocean water off a rocky reef accompanied by an ominous subterranean swell, pure foley, no human voice", duration_seconds=2.6, placement="overlay_next", gap_after_s=0.18, director_note="魔鬼礁海面浮起诡异黑影"),
        dlg("c02_41", "act2", "mad_elder", "扎多克·艾伦", "[terrified] [shouting] 闭嘴！快看海面！礁石边冒出个绿脑袋——他们看见咱们说话了！完了！快滚！千万别走大路，谁留你过夜都别答应——快逃命吧小子！", stability=0.0, gap_after_s=0.30),
        # --- ACT 3: Bus Sabotage + Gilman House Lock-Picking + Three Connecting Rooms + Railway Torch March ---
        dlg("c02_42", "act3", "narrator_deep", "档案片旁白", "九十六岁的老疯子像撞了鬼一样嚎叫着钻进死巷，瞬间没了踪影。奥姆斯特德背脊发凉，一路小跑赶回镇广场车站，可天色已沉，那辆破班车正掀着引擎盖冒黑烟。", gap_after_s=0.24),
        sfx("c02_43", "act3", "Old bus starter motor cranking weakly and dying with a hollow metallic clunk as dusk coastal fog sweeps across empty stone streets, pure foley, no human voice", duration_seconds=2.8, gap_after_s=0.20, director_note="晚班车故意抛锚"),
        dlg("c02_44", "act3", "sinister_stranger", "司机乔·萨金特", "[coldly] [sarcastic] 真不巧啊外乡人，缸体裂了，今晚发不了车。全镇没多余汽车，电话线也让海风刮断了。乖乖去街对面吉尔曼旅馆睡一晚，明早再说吧。", stability=0.0, gap_after_s=0.24),
        dlg("c02_45", "act3", "young_investigator", "罗伯特·奥姆斯特德", "[whispers] [terrified] 他在撒谎……我明明看见引擎连火花塞都被人故意拔松了！街头巷尾已经有五六个人影在朝这边靠拢，他故意把我困在印斯茅斯过夜！", stability=0.0, acoustic_space="mental_realm", gap_after_s=0.24),
        sfx("c02_46", "act3", "Creaking narrow wooden hotel staircase climbing to the third floor followed by an iron room key clicking in a dry rusty door lock, pure foley, no human voice", duration_seconds=2.8, gap_after_s=0.20, director_note="入住吉尔曼旅馆三楼客房"),
        dlg("c02_47", "act3", "sinister_stranger", "吉尔曼旅馆前台", "[coldly] [eerie] 三楼四二八号房。夜里海风大，不管走廊听见什么动静，外乡人，都别探出头来多管闲事。", stability=0.0, gap_after_s=0.24),
        dlg("c02_48", "act3", "narrator_deep", "档案片旁白", "阴湿发霉的四二八号房里，墙纸像腐皮一样卷落，浓重鱼腥顺着地板缝直往上钻。奥姆斯特德冷汗直冒地发现：走廊门竟然没有内插销，只有一把松垮的老锁，左右两面墙各有一道连通相邻空房的旧木门。", gap_after_s=0.26),
        dlg("c02_49", "act3", "young_investigator", "罗伯特·奥姆斯特德", "[whispers] [calmly] 冷静……还好门后有把旧插销勉强能顶住门缝。我不脱衣服、不脱鞋，把杂货店小伙的手绘地图攥紧在手里，借着窗外微弱路灯光，先探清左右连通门的门栓！", stability=0.0, acoustic_space="mental_realm", gap_after_s=0.26),
        sfx("c02_50", "act3", "Distant tarnished town clock tower tolling twice across dead foggy midnight silence, pure foley, no human voice", duration_seconds=2.6, gap_after_s=0.22, director_note="午夜两点钟声敲响"),
        motif("c02_51", "act3", "heavy_wooden_lock_pick", gap_after_s=0.18, director_note="门锁被暗中试探撬动"),
        dlg("c02_52", "act3", "young_investigator", "罗伯特·奥姆斯特德", "[terrified] [whispers] 来了！门把手在一点点往下压……铁丝插进锁孔了！走廊和楼梯口全都是湿答答的沉重脚步！他们不是一个人，是一整群！", stability=0.0, acoustic_space="mental_realm", gap_after_s=0.20),
        sfx("c02_53", "act3", "Soft hurried creaking of a wooden connecting door unbolting followed by heavy thunderous shoulder blows splintering an oak hotel door in the next room, pure foley, no human voice", duration_seconds=3.4, placement="overlay_next", gap_after_s=0.16, director_note="撬开连通门撞碎原房门"),
        dlg("c02_54", "act3", "sinister_stranger", "旅馆前台追兵", "[angry] [hoarsely] 撞开了！屋里没人——右边连通门栓被拉开了！快分头包抄走廊，他躲进四三〇空房了！", stability=0.0, gap_after_s=0.20),
        dlg("c02_55", "act3", "young_investigator", "罗伯特·奥姆斯特德", "[rushed] [whispers] 反锁四三〇的门！再钻进四三二！前厅楼梯全被堵死了——往前摸，穿过第三间空房，尽头那扇通往后巷顶棚的小窗还开着缝！", stability=0.0, acoustic_space="mental_realm", gap_after_s=0.20),
        dlg("c02_56", "act3", "narrator_deep", "档案片旁白", "[dramatically] 生死只在一线之间！追兵斧劈似的撞击声紧贴着身后一墙之隔！奥姆斯特德屏住呼吸连穿三间积满厚灰的空房，在第二道门板轰然碎裂的刹那，翻出三楼后窗顺着腐朽木梯滑进漆黑暗巷！", stability=0.0, gap_after_s=0.24),
        sfx("c02_57", "act3", "Urgent sliding wooden window sash slamming open with frantic boots scraping down wet rotting wooden fire escape stairs onto foggy cobblestones, pure foley, no human voice", duration_seconds=3.2, placement="overlay_next", gap_after_s=0.16, director_note="连穿三间空房翻窗逃入暗巷"),
        dlg("c02_58", "act3", "young_investigator", "罗伯特·奥姆斯特德", "[rushed] [terrified] 大桥和公路口全举着灯笼封死了！只剩杂货店小伙画的那条荒废铁轨！往北跑，贴着杂草丛往荒野铁轨跑！", stability=0.0, acoustic_space="mental_realm", gap_after_s=0.22),
        sfx("c02_59", "act3", "Fast crunching footsteps sprinting over rusted railroad gravel ties abruptly diving flat into dense rustling thorny roadside bushes, pure foley, no human voice", duration_seconds=3.0, gap_after_s=0.20, director_note="狂奔荒废铁轨扑进灌木丛"),
        dlg("c02_60", "act3", "narrator_deep", "档案片旁白", "冲出小镇两英里，前方平行大路突然亮起一片摇晃的火把！浓雾里飘来令人窒息的烂鱼腥气。奥姆斯特德一头扎进路边带刺灌木丛，死死捂住口鼻，因为那支庞大队列正从十步外缓缓走过！", gap_after_s=0.24),
        sfx("c02_61", "act3", "Scores of wet slapping amphibian footsteps marching rhythmically down a gravel coastal highway with crackling pitch torches and hollow marine shells rattling in thick fog, pure foley, no human voice", duration_seconds=3.6, gap_after_s=0.20, director_note="深潜者火把游行经过灌木丛"),
        dlg("c02_62", "act3", "cultist_buzzing", "深潜者群潮", "[hoarsely] [eerie] 咕噜……拉莱耶……达贡……那外乡人逃不远……搜遍铁轨两侧……活捉祭海……", stability=0.0, acoustic_space="mental_realm", gap_after_s=0.24),
        dlg("c02_63", "act3", "young_investigator", "罗伯特·奥姆斯特德", "[terrified] [whispers] 月亮突然撕开云层了……老天爷啊！举着火把走在前头的根本不是穿斗篷的人！他们全身灰绿滑亮、肚子发白、背脊长满硬鳍、一蹦一跳像直立巨蛙——头上还戴着博物馆里那种黄金头冠！", stability=0.0, acoustic_space="mental_realm", gap_after_s=0.32),
        # --- ACT 4: Federal Raid + Genealogy Discovery + Bathroom Mirror Transformation ---
        dlg("c02_64", "act4", "narrator_deep", "档案片旁白", "奥姆斯特德在灌木丛中直接吓昏过去，直到清晨阳光刺眼才爬起身，拖着满身荆棘血痕逃进邻镇罗利，向联邦当局和盘托出。那年冬天，武装部队秘密突袭印斯茅斯，封锁街道并炸毁了临海旧宅。", gap_after_s=0.26),
        sfx("c02_65", "act4", "Muffled distant naval depth charges detonating deep underwater beneath dark coastal ocean waves with low seismic rumble, pure foley, no human voice", duration_seconds=3.2, gap_after_s=0.22, director_note="潜艇向魔鬼礁发射深水炸弹"),
        dlg("c02_66", "act4", "young_investigator", "罗伯特·奥姆斯特德", "[calmly] [softly] 海军潜艇甚至往魔鬼礁深沟里投下了好几枚深水炸弹。我以为噩梦终于结束了，搬回老家安心读书。直到去年冬天，鬼使神差之下，我翻开了母亲留下的家族谱系与一只上锁的首饰盒。", acoustic_space="studio_warm", gap_after_s=0.26),
        sfx("c02_67", "act4", "Heavy antique leather-bound family genealogy ledger opening with brittle yellowed parchment pages turning slowly under a quiet study lamp, pure foley, no human voice", duration_seconds=2.6, gap_after_s=0.20, director_note="翻开家族谱系查出惊天身世"),
        dlg("c02_68", "act4", "young_investigator", "罗伯特·奥姆斯特德", "[hoarsely] [trembling] 首饰盒里躺着一只微缩版白金海怪头冠，跟纽伯里波特展柜里那顶一模一样！再翻开族谱，我浑身血液瞬间冰凉——我的外祖母娘家竟然就姓马什！", stability=0.0, acoustic_space="studio_warm", gap_after_s=0.26),
        dlg("c02_69", "act4", "young_investigator", "罗伯特·奥姆斯特德", "[terrified] [whispers] 她就是印斯茅斯奥贝德·马什船长与那位“神秘南海妻子”的亲孙女！我终于懂了，为什么舅舅看清家族画像后举枪自尽，为什么表哥一直被锁在州立疯人院的暗室里！", stability=0.0, acoustic_space="studio_warm", gap_after_s=0.28),
        dlg("c02_70", "act4", "eldritch_whisper", "深海召唤", "[haunting] [whispers] 回来吧……你的血记得海水……在魔鬼礁下的万年石殿里，没有衰老，没有死亡……", stability=0.0, acoustic_space="mental_realm", gap_after_s=0.26),
