        dlg("c03_04", "act1", "female_archivist", "阿卡姆档案员", "[seriously] 档案编号零零三：《星之彩》。一九二七年秋，波士顿水利勘测工程师受命赴阿卡姆西郊规划新水库，在辞职前夕向特藏室移交了这份连夜录下的老农证词。", acoustic_space="studio_warm", gap_after_s=0.26),
